function crossNorm(rightSide, leftSide) {
    let total = 0;
    const stop = Math.min(rightSide.length, leftSide.length);
    for (let idx = 0; idx < stop; idx++) {
        total = total + rightSide[idx] * leftSide[idx];
    }
    return total;
}

